import { NextResponse } from "next/server";
import { z } from "zod";
import { createServerSupabase } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { normalizeGhanaPhone } from "@/lib/phone";
const schema=z.object({businessName:z.string().trim().min(2).max(80).optional(),about:z.string().max(300).nullable(),address:z.string().max(200).nullable(),category:z.string().max(60).nullable(),whatsappNumber:z.string(),acceptingOrders:z.boolean(),bannerPath:z.string().max(600).nullable(),logoPath:z.string().max(600).nullable()});
export async function PATCH(request:Request){try{const auth=await createServerSupabase();const {data:{user}}=await auth.auth.getUser();if(!user)return NextResponse.json({error:"Please log in."},{status:401});const parsed=schema.safeParse(await request.json());if(!parsed.success)return NextResponse.json({error:"Check the storefront details."},{status:400});const v=parsed.data;const phone=normalizeGhanaPhone(v.whatsappNumber);if(!phone)return NextResponse.json({error:"Enter a 10-digit WhatsApp number, like 024 123 4567."},{status:400});const db=createAdminClient();const {data:vendor}=await db.from("vendors").select("id").eq("owner_id",user.id).single();if(!vendor)return NextResponse.json({error:"Shop not found."},{status:404});for(const path of [v.bannerPath,v.logoPath]){if(path&&!path.startsWith(`${vendor.id}/`))return NextResponse.json({error:"That image does not belong to your shop."},{status:400});}const {data,error}=await db.from("vendors").update({...(v.businessName?{business_name:v.businessName}:{}),about:v.about,address:v.address,category:v.category,whatsapp_number:phone,accepting_orders:v.acceptingOrders,banner_path:v.bannerPath,logo_path:v.logoPath}).eq("id",vendor.id).select("business_name,slug,about,address,category,whatsapp_number,accepting_orders,banner_path,logo_path").single();if(error)throw error;return NextResponse.json({vendor:data});}catch{return NextResponse.json({error:"Storefront changes could not be saved."},{status:503});}}
